import { Mesh, Group, PlaneGeometry, BoxGeometry, CircleGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  const timelines = [];
  const primitiveCleanups = [];
  const resources = [];
  const ownedMaterials = [];
  const ownedGeometries = [];

  const makeBasic = (params = {}) => {
    const material = new MeshBasicNodeMaterial(params);
    ownedMaterials.push(material);
    return material;
  };

  const makeStandard = (params = {}) => {
    const material = new MeshStandardNodeMaterial(params);
    ownedMaterials.push(material);
    return material;
  };

  const makeGeometry = (GeometryClass, ...args) => {
    const geometry = new GeometryClass(...args);
    ownedGeometries.push(geometry);
    return geometry;
  };

  // Designed dark stage: ink-to-surface vertical engineered gradient.
  const backdropMaterial = makeBasic();
  backdropMaterial.colorNode = mix(
    color('#0b0b10'),
    color('#16161d'),
    uv().y
  );

  const backdrop = new Mesh(
    makeGeometry(PlaneGeometry, 7, 6),
    backdropMaterial
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // Grounding plane adds a third depth plane without introducing an unlit void.
  const shadowMaterial = makeBasic({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new Mesh(
    makeGeometry(CircleGeometry, 1.35, 48),
    shadowMaterial
  );
  contactShadow.scale.set(1.55, 0.42, 1);
  contactShadow.position.set(0, -0.92, -0.18);
  root.add(contactShadow);

  const card = new Group();
  root.add(card);

  // Low-gloss machined backing keeps the interactive plane grounded and dimensional.
  const backingMaterial = makeStandard({
    color: '#16161d',
    roughness: 0.62,
    metalness: 0.42
  });
  const backing = new Mesh(
    makeGeometry(BoxGeometry, 3.02, 1.82, 0.12),
    backingMaterial
  );
  backing.position.z = 0;
  card.add(backing);

  const imageMaterial = makeStandard({
    color: '#e8ecf2',
    roughness: 0.58,
    metalness: 0.18
  });
  const imagePlane = new Mesh(
    makeGeometry(PlaneGeometry, 2.84, 1.64),
    imageMaterial
  );
  imagePlane.position.z = 0.075;
  card.add(imagePlane);

  const edgeMaterial = makeStandard({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.15,
    roughness: 0.52,
    metalness: 0.28
  });

  const edge = new Mesh(
    makeGeometry(BoxGeometry, 0.035, 1.58, 0.035),
    edgeMaterial
  );
  edge.position.set(1.405, 0, 0.13);
  edge.visible = false;
  card.add(edge);

  const topAccent = new Mesh(
    makeGeometry(BoxGeometry, 0.56, 0.035, 0.035),
    edgeMaterial
  );
  topAccent.position.set(-1.1, 0.78, 0.13);
  topAccent.visible = false;
  card.add(topAccent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? 'body';
    const fontSize =
      item.typography?.fontSize ??
      (role === 'hero' ? 0.62 :
        role === 'headline' ? 0.34 :
          role === 'subhead' ? 0.2 :
            role === 'caption' ? 0.09 : 0.13);

    const label = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: role === 'caption' ? '#ff2a38' : '#e8ecf2',
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    label.position.set(-1.08, 0.56 - items.indexOf(item) * 0.22, 0.15);
    card.add(label);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const baseY = card.position.y;
  const hoverLift = 0.15;
  let hoverTween = null;

  const animateHover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(card.position, {
      y: baseY + hoverLift,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(hoverTween);
  };

  const animateLeave = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(card.position, {
      y: baseY,
      duration: 0.55,
      ease: 'power3.out'
    });
    timelines.push(hoverTween);
  };

  root.userData.handlers = {
    hover: animateHover,
    pointerout: animateLeave,
    blur: () => {
      edge.visible = false;
      topAccent.visible = false;
      animateLeave();
    },
    focus: () => {
      edge.visible = true;
      topAccent.visible = true;
    },
    click: () => {
      const press = gsap.timeline();
      press.to(card.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      }).to(card.scale, {
        x: 1,
        y: 1,
        duration: 0.32,
        ease: 'back.out(2)'
      });
      timelines.push(press);
      ctx.emit('hub-pricing.select', {
        node: config.id ?? config.name ?? 'pricing-quote-panel'
      });
    }
  };

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.position,
    { y: baseY + 0.4 },
    { y: baseY, duration: 0.7, ease: 'power3.out' }
  );
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') {
      primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const cleanup of primitiveCleanups) cleanup();

    for (const texture of resources) {
      if (texture && typeof texture.dispose === 'function') texture.dispose();
    }

    for (const material of ownedMaterials) {
      if (material && typeof material.dispose === 'function') material.dispose();
    }

    for (const geometry of ownedGeometries) {
      if (geometry && typeof geometry.dispose === 'function') geometry.dispose();
    }
  };

  return root;
}
